INSERT INTO `contacts` VALUES (4, 'EIAD ALSHAIKH DARWISH', 'eiaddar@gmail.com', '0944408833', 'International Commercial Arbitration Course', '🏢 مجالات العمل المتاحة:\n1. القطاع الحكومي والهيئات الرقمية الوطنية:\nهيئات التحول الرقمي.\n\nهيئات الأمن السيبراني.\n\nالوزارات ذات البنية التقنية الكبيرة (الداخلية، المالية، الصحة).\n\n2. القطاع المصرفي والمالي:\nإدارة البنية التقنية والأمنية.\n\nتطوير أنظمة الدفع والخدمات الرقمية.\n\n3. شركات التقنية والاتصالات:\nشركات البرمجة والتطوير الكبيرة.\n\nمشغلي الاتصالات (مثل MTN، سيرياتيل).\n\nشركات الحلول السحابية والأمن السيبراني.', 0, NULL, '2026-01-23 14:28:44', '2026-01-23 14:28:44');
