INSERT INTO `position_applications` VALUES (4, 4, 'Eiad Darwish', 'e.darwish@aldrtechnology.com', '0944408833', 'We are seeking a strategic and creative Marketing Manager to lead our brand\'s marketing efforts. You will be responsible for developing and executing integrated marketing campaigns that drive brand awareness, customer engagement, and sales growth across the MENA region. The ideal candidate is a beauty enthusiast with a strong blend of analytical and creative skills.', 'We are seeking a strategic and creative Marketing Manager to lead our brand\'s marketing efforts. You will be responsible for developing and executing integrated marketing campaigns that drive brand awareness, customer engagement, and sales growth across the MENA region. The ideal candidate is a beauty enthusiast with a strong blend of analytical and creative skills.', 0, NULL, 'position-applications/cvs/P82irhNpN27m9GAoFFxLJEUZEHYBK6WMNp9DChOr.pdf', '5829.pdf', 1, '2026-01-25 12:05:48', '2026-01-25 09:23:41', '2026-01-25 12:05:48', NULL);
INSERT INTO `position_applications` VALUES (3, 4, 'EIAD ALSHAIKH DARWISH', 'eiaddar@gmail.com', '0944408833', '012507', '012507', 1, '2026-01-25 07:57:34', 'position-applications/cvs/dRSuFhoYgqIl2GHhLToNM1SAmMP3j5ljLtuDfzCp.pdf', '5829.pdf', 1, '2026-01-25 12:07:55', '2026-01-25 07:56:36', '2026-01-25 12:07:55', NULL);
INSERT INTO `position_translations` VALUES (1, 1, 'en', 'Marketing Manager - Beauty & Cosmetics', 'We are seeking a strategic and creative Marketing Manager to lead our brand\'s marketing efforts. You will be responsible for developing and executing integrated marketing campaigns that drive brand awareness, customer engagement, and sales growth across the MENA region. The ideal candidate is a beauty enthusiast with a strong blend of analytical and creative skills.', 'Bachelor\'s degree in Marketing, Business, or a related field.\n\n5+ years of marketing experience, with at least 3 years in the beauty, skincare, or FMCG industry.\n\nProven track record of managing successful, multi-channel marketing campaigns.\n\nDeep understanding of the beauty landscape and consumer behavior in the MENA region.\n\nExpertise in social media marketing and digital analytics (Google Analytics, social insights).\n\nExcellent communication, presentation, and project management skills.\n\nFluency in English and Arabic is essential.', 'Develop and implement the annual marketing strategy and budget.\n\nLead 360-degree marketing campaigns (Digital, Social Media, PR, Influencer, Retail).\n\nManage and grow the brand\'s social media presence (Instagram, TikTok, Snapchat, etc.) with locally relevant content.\n\nAnalyze market trends, consumer insights, and competitor activity to identify opportunities.\n\nCollaborate with E-commerce and Sales teams to develop promotional plans and optimize conversion.\n\nBuild and manage relationships with key influencers, media, and beauty partners.\n\nOversee the creation of all marketing materials, ensuring brand consistency.\n\nTrack, measure, and report on campaign performance using KPIs and analytics tools.', NULL, NULL, NULL);
INSERT INTO `position_translations` VALUES (2, 4, 'en', 'Marketing Manager - Beauty & Cosmetics', 'We are seeking a strategic and creative Marketing Manager to lead our brand\'s marketing efforts. You will be responsible for developing and executing integrated marketing campaigns that drive brand awareness, customer engagement, and sales growth across the MENA region. The ideal candidate is a beauty enthusiast with a strong blend of analytical and creative skills.', 'Bachelor\'s degree in Marketing, Business, or a related field.\n\n5+ years of marketing experience, with at least 3 years in the beauty, skincare, or FMCG industry.\n\nProven track record of managing successful, multi-channel marketing campaigns.\n\nDeep understanding of the beauty landscape and consumer behavior in the MENA region.\n\nExpertise in social media marketing and digital analytics (Google Analytics, social insights).\n\nExcellent communication, presentation, and project management skills.\n\nFluency in English and Arabic is essential.', 'Develop and implement the annual marketing strategy and budget.\n\nLead 360-degree marketing campaigns (Digital, Social Media, PR, Influencer, Retail).\n\nManage and grow the brand\'s social media presence (Instagram, TikTok, Snapchat, etc.) with locally relevant content.\n\nAnalyze market trends, consumer insights, and competitor activity to identify opportunities.\n\nCollaborate with E-commerce and Sales teams to develop promotional plans and optimize conversion.\n\nBuild and manage relationships with key influencers, media, and beauty partners.\n\nOversee the creation of all marketing materials, ensuring brand consistency.\n\nTrack, measure, and report on campaign performance using KPIs and analytics tools.', 'Join us', NULL, NULL);
INSERT INTO `position_translations` VALUES (3, 1, 'ar', 'العناية بالبشرة والجسم', 'نبحث عن مدير تسويق استراتيجي ومبدع لقيادة جهود التسويق لعلامتنا التجارية. ستكون مسؤولاً عن تطوير وتنفيذ حملات تسويقية متكاملة تهدف إلى تعزيز الوعي بالعلامة التجارية، ومشاركة العملاء، وتحقيق نمو المبيعات في منطقة الشرق الأوسط وشمال أفريقيا. المرشح المثالي هو محب لمجال الجمال ويجمع بين المهارات التحليلية والإبداعية.\n\n', 'تطوير وتنفيذ استراتيجية التسويق والميزانية السنوية.\n\nقيادة الحملات التسويقية المتكاملة (التسويق الرقمي، وسائل التواصل الاجتماعي، العلاقات العامة، التعامل مع المؤثرين، التسويق بالتجزئة).\n\nإدارة وتنمية حضور العلامة التجارية على منصات التواصل الاجتماعي (إنستغرام، تيك توك، سناب شات، وغيرها) من خلال محتوى ذي صلة بالأسواق المحلية.\n\nتحليل اتجاهات السوق، وبيانات المستهلكين، ونشاط المنافسين لتحديد الفرص.\n\nالتعاون مع فرعي التجارة الإلكترونية والمبيعات لوضع خطط ترويجية وتحسين معدلات التحويل.\n\nبناء وإدارة العلاقات مع المؤثرين الرئيسيين، ووسائل الإعلام، وشركاء الصناعة.\n\nالإشراف على إنشاء جميع المواد التسويقية، وضمان اتساقها مع هوية العلامة التجارية.\n\nتتبع وقياس وتقارير أداء الحملات باستخدام مؤشرات الأداء الرئيسية وأدوات التحليلات', 'درجة البكالوريوس في التسويق، إدارة الأعمال، أو مجال ذي صلة.\n\nخبرة لا تقل عن 5 سنوات في مجال التسويق، بما في ذلك 3 سنوات على الأقل في صناعة الجمال، العناية بالبشرة، أو سلع الاستهلاك السريع.\n\nسجل حافل بإدارة حملات تسويقية ناجحة ومتعددة القنوات.\n\nفهم عميق لبيئة صناعة الجمال وسلوك المستهلك في منطقة الشرق الأوسط وشمال أفريقيا.\n\nخبرة في تسويق وسائل التواصل الاجتماعي والتحليلات الرقمية (مثل Google Analytics).\n\n', 'انضم الينا', NULL, NULL);
INSERT INTO `position_translations` VALUES (4, 4, 'ar', 'فني صيانة', 'درجة البكالوريوس في التسويق، إدارة الأعمال، أو مجال ذي صلة.\n\nخبرة لا تقل عن 5 سنوات في مجال التسويق، بما في ذلك 3 سنوات على الأقل في صناعة الجمال، العناية بالبشرة، أو سلع الاستهلاك السريع.\n\nسجل حافل بإدارة حملات تسويقية ناجحة ومتعددة القنوات.\n\nفهم عميق لبيئة صناعة الجمال وسلوك المستهلك في منطقة الشرق الأوسط وشمال أفريقيا.\n\nخبرة في تسويق وسائل التواصل الاجتماعي والتحليلات الرقمية (مثل Google Analytics).\n\n', 'درجة البكالوريوس في التسويق، إدارة الأعمال، أو مجال ذي صلة.\n\nخبرة لا تقل عن 5 سنوات في مجال التسويق، بما في ذلك 3 سنوات على الأقل في صناعة الجمال، العناية بالبشرة، أو سلع الاستهلاك السريع.\n\nسجل حافل بإدارة حملات تسويقية ناجحة ومتعددة القنوات.\n\nفهم عميق لبيئة صناعة الجمال وسلوك المستهلك في منطقة الشرق الأوسط وشمال أفريقيا.\n\nخبرة في تسويق وسائل التواصل الاجتماعي والتحليلات الرقمية (مثل Google Analytics).\n\n', 'درجة البكالوريوس في التسويق، إدارة الأعمال، أو مجال ذي صلة.\n\nخبرة لا تقل عن 5 سنوات في مجال التسويق، بما في ذلك 3 سنوات على الأقل في صناعة الجمال، العناية بالبشرة، أو سلع الاستهلاك السريع.\n\nسجل حافل بإدارة حملات تسويقية ناجحة ومتعددة القنوات.\n\nفهم عميق لبيئة صناعة الجمال وسلوك المستهلك في منطقة الشرق الأوسط وشمال أفريقيا.\n\nخبرة في تسويق وسائل التواصل الاجتماعي والتحليلات الرقمية (مثل Google Analytics).\n\n', 'انضم الينا', NULL, NULL);
